import React, { useEffect, useState } from 'react';
import { Card, CardHeader, Table, Btn, Badge, Modal, FormRow, FormField, SearchBar, Spinner } from '../components/ui/Card';
import api from '../utils/api';
import toast from 'react-hot-toast';
import { useAuth } from '../contexts/AuthContext';

const SERVICES = ['Direction', 'Administration', 'Logistique', 'Communication', 'Mobilisation', 'Technique'];
const CONTRATS = ['CDI', 'CDD', 'Bénévole', 'Stage', 'Autre'];
const STATUTS_FAMILLE = ['Célibataire', 'Marié(e)', 'Divorcé(e)', 'Veuf/Veuve'];

const defaultForm = {
  nom: '', prenom: '', nom_jeune_fille: '', date_naissance: '', lieu_naissance: '',
  adresse: '', telephone: '', email: '', situation_familiale: 'Célibataire',
  contact_urgence_nom: '', contact_urgence_tel: '',
  poste: '', service: 'Administration', type_contrat: 'CDI', date_entree: '',
  superieur: '', cnaps: '', aro: '', statut: 'actif'
};

export default function PersonnelPage() {
  const { hasRole } = useAuth();
  const [personnel, setPersonnel] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterService, setFilterService] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(defaultForm);
  const [saving, setSaving] = useState(false);

  const canEdit = hasRole('super_admin', 'assistant_admin');

  useEffect(() => {
    document.getElementById('page-title') && (document.getElementById('page-title').textContent = 'Gestion du Personnel');
    loadPersonnel();
  }, []);

  const loadPersonnel = async () => {
    setLoading(true);
    try {
      const r = await api.get('/personnel');
      setPersonnel(r.data.data);
    } catch (e) { toast.error('Erreur de chargement'); }
    finally { setLoading(false); }
  };

  const filtered = personnel.filter(p => {
    const s = search.toLowerCase();
    const matchSearch = !s || p.nom?.toLowerCase().includes(s) || p.prenom?.toLowerCase().includes(s) || p.matricule?.toLowerCase().includes(s) || p.poste?.toLowerCase().includes(s);
    const matchService = !filterService || p.service === filterService;
    return matchSearch && matchService;
  });

  const openModal = (p = null) => {
    setEditing(p);
    setForm(p ? { ...defaultForm, ...p } : defaultForm);
    setModalOpen(true);
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editing) {
        await api.put(`/personnel/${editing.id}`, form);
        toast.success('Personnel mis à jour');
      } else {
        await api.post('/personnel', form);
        toast.success('Personnel créé');
      }
      setModalOpen(false);
      loadPersonnel();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Erreur');
    } finally { setSaving(false); }
  };

  const handleDeactivate = async (id) => {
    if (!window.confirm('Désactiver ce membre du personnel ?')) return;
    try {
      await api.delete(`/personnel/${id}`);
      toast.success('Personnel désactivé');
      loadPersonnel();
    } catch { toast.error('Erreur'); }
  };

  const columns = [
    { key: 'matricule', header: 'Matricule', render: v => <span style={{ fontFamily: 'monospace', fontWeight: 700, color: 'var(--navy)', fontSize: '0.83rem' }}>{v}</span> },
    { key: 'nom', header: 'Nom & Prénom', render: (_, row) => (
      <div>
        <p style={{ fontWeight: 600, color: 'var(--navy)' }}>{row.prenom} {row.nom}</p>
        <p style={{ fontSize: '0.75rem', color: 'var(--gray-400)' }}>{row.email}</p>
      </div>
    )},
    { key: 'poste', header: 'Poste' },
    { key: 'service', header: 'Service', render: v => <Badge type="info">{v}</Badge> },
    { key: 'type_contrat', header: 'Contrat', render: v => <Badge type="gold">{v}</Badge> },
    { key: 'statut', header: 'Statut', render: v => <Badge type={v === 'actif' ? 'success' : 'error'}>{v}</Badge> },
    { key: 'actions', header: 'Actions', render: (_, row) => (
      <div style={{ display: 'flex', gap: 6 }}>
        <Btn size="sm" variant="secondary" onClick={() => openModal(row)}>✏️</Btn>
        {canEdit && <Btn size="sm" variant="danger" onClick={() => handleDeactivate(row.id)}>🗑️</Btn>}
      </div>
    )}
  ];

  return (
    <div className="animate-fade">
      <Card style={{ marginBottom: 20 }}>
        <CardHeader
          title="Gestion du Personnel"
          subtitle={`${filtered.length} membre(s) trouvé(s)`}
          action={canEdit && <Btn variant="gold" onClick={() => openModal()}>➕ Nouveau membre</Btn>}
        />
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          <div style={{ flex: 1, minWidth: 200 }}>
            <SearchBar value={search} onChange={setSearch} placeholder="Rechercher par nom, poste..." />
          </div>
          <select value={filterService} onChange={e => setFilterService(e.target.value)} style={{ width: 'auto', minWidth: 160 }}>
            <option value="">Tous les services</option>
            {SERVICES.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
      </Card>

      <Card>
        {loading ? <Spinner /> : <Table columns={columns} data={filtered} emptyMessage="Aucun personnel enregistré" />}
      </Card>

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? `Modifier — ${editing.prenom} ${editing.nom}` : 'Nouveau membre du personnel'} width={700}>
        <form onSubmit={handleSave} style={{ padding: '24px' }}>
          {/* Section A */}
          <div style={{ marginBottom: 20, paddingBottom: 16, borderBottom: '1px solid var(--gray-100)' }}>
            <h4 style={{ color: 'var(--gold-dark)', fontWeight: 700, fontSize: '0.78rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 14 }}>A — Informations personnelles</h4>
            <FormRow>
              <FormField label="Prénom" required><input value={form.prenom} onChange={e => setForm({...form, prenom: e.target.value})} required /></FormField>
              <FormField label="Nom" required><input value={form.nom} onChange={e => setForm({...form, nom: e.target.value})} required /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Date de naissance"><input type="date" value={form.date_naissance} onChange={e => setForm({...form, date_naissance: e.target.value})} /></FormField>
              <FormField label="Lieu de naissance"><input value={form.lieu_naissance} onChange={e => setForm({...form, lieu_naissance: e.target.value})} /></FormField>
            </FormRow>
            <FormRow cols={1}>
              <FormField label="Adresse"><input value={form.adresse} onChange={e => setForm({...form, adresse: e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Téléphone"><input value={form.telephone} onChange={e => setForm({...form, telephone: e.target.value})} /></FormField>
              <FormField label="Email"><input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} /></FormField>
            </FormRow>
            <FormRow>
              <FormField label="Situation familiale">
                <select value={form.situation_familiale} onChange={e => setForm({...form, situation_familiale: e.target.value})}>
                  {STATUTS_FAMILLE.map(s => <option key={s}>{s}</option>)}
                </select>
              </FormField>
              <div />
            </FormRow>
            <FormRow>
              <FormField label="Contact urgence — Nom"><input value={form.contact_urgence_nom} onChange={e => setForm({...form, contact_urgence_nom: e.target.value})} /></FormField>
              <FormField label="Contact urgence — Tél."><input value={form.contact_urgence_tel} onChange={e => setForm({...form, contact_urgence_tel: e.target.value})} /></FormField>
            </FormRow>
          </div>

          {/* Section B */}
          <div style={{ marginBottom: 20, paddingBottom: 16, borderBottom: '1px solid var(--gray-100)' }}>
            <h4 style={{ color: 'var(--gold-dark)', fontWeight: 700, fontSize: '0.78rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 14 }}>B — Informations professionnelles</h4>
            <FormRow>
              <FormField label="Poste" required><input value={form.poste} onChange={e => setForm({...form, poste: e.target.value})} required /></FormField>
              <FormField label="Service" required>
                <select value={form.service} onChange={e => setForm({...form, service: e.target.value})}>
                  {SERVICES.map(s => <option key={s}>{s}</option>)}
                </select>
              </FormField>
            </FormRow>
            <FormRow>
              <FormField label="Type de contrat">
                <select value={form.type_contrat} onChange={e => setForm({...form, type_contrat: e.target.value})}>
                  {CONTRATS.map(c => <option key={c}>{c}</option>)}
                </select>
              </FormField>
              <FormField label="Date d'entrée"><input type="date" value={form.date_entree} onChange={e => setForm({...form, date_entree: e.target.value})} /></FormField>
            </FormRow>
          </div>

          {/* Section D */}
          <div>
            <h4 style={{ color: 'var(--gold-dark)', fontWeight: 700, fontSize: '0.78rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 14 }}>D — Administratif</h4>
            <FormRow>
              <FormField label="N° CNAPS"><input value={form.cnaps} onChange={e => setForm({...form, cnaps: e.target.value})} /></FormField>
              <FormField label="N° ARO"><input value={form.aro} onChange={e => setForm({...form, aro: e.target.value})} /></FormField>
            </FormRow>
          </div>

          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', paddingTop: 20, borderTop: '1px solid var(--gray-100)', marginTop: 8 }}>
            <Btn type="button" variant="secondary" onClick={() => setModalOpen(false)}>Annuler</Btn>
            <Btn type="submit" variant="gold" disabled={saving}>{saving ? 'Enregistrement...' : editing ? '💾 Mettre à jour' : '➕ Créer'}</Btn>
          </div>
        </form>
      </Modal>
    </div>
  );
}
